// Minimal service worker — intentionally hand-written rather than
// generated by a build plugin (avoids the vite-plugin-pwa/workbox-build
// dynamic-require bug seen in some build environments).
//
// Responsibilities, deliberately kept small:
//   1. Register a 'fetch' handler — required for Chrome/Android to consider
//      the site installable at all. We pass every request straight to the
//      network; this app is live multiplayer state, not offline content, so
//      there's nothing worth precaching or serving stale.
//   2. Let the page call `registration.showNotification(...)` directly (the
//      "return to the app" reminder) — this works on any active service
//      worker without extra wiring here.
//   3. Focus/open the app when a notification is tapped.

const CACHE_NAME = 'pandora-bingo-shell-v1';

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener('fetch', (event) => {
  // Deliberate pass-through. Never intercept API calls, auth redirects, or
  // Socket.io's websocket/polling transport — all of those need live
  // network access every time, not a cached response.
  event.respondWith(fetch(event.request));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if ('focus' in client) return client.focus();
      }
      if (self.clients.openWindow) return self.clients.openWindow('/');
    })
  );
});
